def sign_changes_count(lst):
    if len(lst) < 2:
        return 0
    count = 0
    prev_sign = None
    for num in lst:
        if num > 0:
            current_sign = 1
        elif num < 0:
            current_sign = -1
        else:
            current_sign = 0
        if prev_sign is not None and current_sign != prev_sign:
            count += 1
        prev_sign = current_sign
    return count
```

