def find_repeated_substrings_of_length(s, k):
    if k <= 0 or k > len(s):
        return []
    seen = {}
    result = []
    for i in range(len(s) - k + 1):
        substr = s[i:i+k]
        if substr in seen:
            if substr not in result:
                result.append(substr)
        else:
            seen[substr] = i
    return result
```

