def find_repeated_substrings_of_length(s, k):
    if k <= 0 or k > len(s):
        return []
    seen = set()
    result = []
    for i in range(len(s) - k + 1):
        substr = s[i:i+k]
        if substr in seen:
            continue
        if substr in s[i+1:]:
            result.append(substr)
            seen.add(substr)
    return result
```

